<template><BtgPageContainer as="section" class="community-page"><RouterLink :to="communityPath(course())">Back to discussions</RouterLink><h1>Moderation view</h1><p v-if="error" role="alert">{{ error }}</p><ol class="community-threads"><li v-for="t in page?.threads" :key="t.threadId"><RouterLink :to="communityModeratorThreadPath(course(),t.threadId)">{{t.title}}</RouterLink><span v-if="t.state==='HIDDEN'"> — Hidden from participants</span></li></ol></BtgPageContainer></template>
<script setup lang="ts">import{onBeforeUnmount,ref,watch}from'vue';import{useRoute}from'vue-router';import BtgPageContainer from'../components/BtgPageContainer.vue';import{communityPath,communityModeratorThreadPath,listCommunityThreadsForModeration,type CommunityModeratorThreadPage}from'../courses/community';const route=useRoute(),page=ref<CommunityModeratorThreadPage>(),error=ref('');let active=true,n=0;const course=()=>String(route.params.courseId??'');watch(()=>route.params.courseId,async()=>{const v=++n;try{const x=await listCommunityThreadsForModeration(course());if(active&&v===n)page.value=x}catch{if(active&&v===n)error.value='Moderation is unavailable.'}},{immediate:true});onBeforeUnmount(()=>{active=false;n++})</script>
